
import type { ImageInput } from './ImageInput.js';
import type { PostalAddressInput } from './PostalAddressInput.js';

export type MerchantInput = { "address"?: PostalAddressInput; /** Default API version for requests without a Flint-Version header. Shared across live and test environments. */ "api_version"?: string; /** When the merchant's default API version last changed. Format: date-time. */ "api_version_changed_at"?: never; /** When the merchant's default API version was first set. Format: date-time. */ "api_version_pinned_at"?: never; /** Previous API version, present while a supported rollback is available. */ "api_version_previous"?: never; /** When the 72-hour rollback offer expires. Explicit changes to any supported version remain available afterward. Format: date-time. */ "api_version_rollback_expires_at"?: never; "banners"?: never; /** Business name buyers see on checkout, payment links, and receipts. Once the merchant starts verification, it stays in sync with the business name on the live Stripe account: a change on either side applies, and the latest change wins. */ "business_name"?: string; /** Merchant's business type. - `other`: A business type Flint does not map yet. */ "business_type"?: never; /** RFC3339 timestamp. Format: date-time. */ "created_at"?: never; /** RFC3339 timestamp. Format: date-time. */ "current_deadline_at"?: never; "email": string; /** Whether Flint's synced readiness projection has past-due account requirements. */ "has_past_due"?: never; /** A square image, at least 128 by 128 pixels, shown where the store needs a small mark: browser tabs and compact headers. */ "icon"?: ImageInput; "logo"?: ImageInput; "merchant_id"?: never; "metadata"?: Record<string, string>; /** RFC3339 timestamp. Format: date-time. */ "observed_at"?: never; /** Activation lifecycle status. A merchant can remain completed after activation while later readiness fields or requirements show current account attention is needed. */ "onboarding_status"?: never; "organization"?: never; "organization_id"?: string; "payments"?: never; "payouts"?: never; "phone"?: string; "reporting_timezone"?: string; "requirements"?: never; "status"?: never; "status_reason"?: never; "support_email"?: string; "support_phone"?: string; "support_url"?: string; /** RFC3339 timestamp. Format: date-time. */ "updated_at"?: never; /** Profile version. Changes made through Flint to the business name, contact details, metadata, organization, support details, logo, or icon advance this version. Readiness updates and business names synced from Stripe do not. Use an exact numeric string, not a floating-point number. Format: int64. minimum: 1. */ "version"?: never; "website_url"?: string; };
